tasks = [
    {"id": 1, "input": "2+2", "expected": "4"},
    {"id": 2, "input": "capital of France", "expected": "Paris"},
    {"id": 3, "input": "capital of Peru", "expected": "Lima"},
]
outputs = {1: "4", 2: "paris", 3: "Lima"}

def exact_match(expected, output):
    return {"passed": expected == output}

results = []
for t in tasks:
    s = exact_match(t["expected"], outputs[t["id"]])
    results.append((t["id"], s["passed"]))
    print(t["id"], t["expected"], outputs[t["id"]], s)

print("accuracy:", sum(p for _, p in results) / len(results))

